import{_ as t,o as e,c as r,a5 as i,j as a}from"./chunks/framework.Bt0SrEfo.js";const c=JSON.parse('{"title":"01 AI 协作核心概念","description":"","frontmatter":{"title":"01 AI 协作核心概念"},"headers":[],"relativePath":"前端/engineering/ai-copilot/01-核心概念.md","filePath":"前端/engineering/ai-copilot/01-核心概念.md","lastUpdated":1792686342000}'),o={name:"前端/engineering/ai-copilot/01-核心概念.md"};function n(h,l,s,d,u,A){return e(),r("div",null,[...l[0]||(l[0]=[i('<h1 id="_01-ai-协作核心概念" tabindex="-1">01 AI 协作核心概念 <a class="header-anchor" href="#_01-ai-协作核心概念" aria-label="Permalink to &quot;01 AI 协作核心概念&quot;">​</a></h1><blockquote><p>弄清楚 AI 协作的思维模型，理解两种模式的本质区别。</p></blockquote><nav class="table-of-contents"><ul><li><a href="#_1-1-两种-ai-使用模式">1.1 两种 AI 使用模式</a></li><li><a href="#_1-2-ai-的能力边界">1.2 AI 的能力边界</a><ul><li><a href="#ai-擅长的事">AI 擅长的事</a></li><li><a href="#ai-不擅长的事">AI 不擅长的事</a></li></ul></li><li><a href="#_1-3-有效协作的核心原则">1.3 有效协作的核心原则</a><ul><li><a href="#原则-1-给-ai-足够上下文">原则 1：给 AI 足够上下文</a></li><li><a href="#原则-2-让-ai-做闭环-不要只做一步">原则 2：让 AI 做闭环，不要只做一步</a></li><li><a href="#原则-3-ai-的输出需要验证">原则 3：AI 的输出需要验证</a></li><li><a href="#原则-4-拆解任务是-ai-能做的前提">原则 4：拆解任务是 AI 能做的前提</a></li></ul></li><li><a href="#_1-4-codex-专属概念">1.4 Codex 专属概念</a><ul><li><a href="#thread-线程">Thread（线程）</a></li><li><a href="#skill-技能">Skill（技能）</a></li><li><a href="#agent-子代理">Agent（子代理）</a></li><li><a href="#worktree-工作树">Worktree（工作树）</a></li></ul></li><li><a href="#_1-5-本章小结">1.5 本章小结</a></li><li><a href="#下一步">下一步</a></li><li><a href="#面试常考">面试常考</a><ul><li><a href="#q1-ai-编程的两种使用模式">Q1:AI 编程的两种使用模式?</a></li><li><a href="#q2-ai-编程的-3-大局限">Q2:AI 编程的 3 大局限?</a></li><li><a href="#q3-有效协作-3-原则">Q3:有效协作 3 原则?</a></li></ul></li></ul></nav><h2 id="_1-1-两种-ai-使用模式" tabindex="-1">1.1 两种 AI 使用模式 <a class="header-anchor" href="#_1-1-两种-ai-使用模式" aria-label="Permalink to &quot;1.1 两种 AI 使用模式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>描述</th><th>举例</th><th>覆盖率</th></tr></thead><tbody><tr><td><strong>AI as Consultant（顾问）</strong></td><td>AI 给建议，人来执行</td><td>问这段代码有什么问题</td><td>~30%</td></tr><tr><td><strong>AI as Agent（代理）</strong></td><td>AI 独立完成，人做决策</td><td>把函数重构并补全测试</td><td>~80%</td></tr></tbody></table><p><strong>大多数人的问题</strong>：一直在用&quot;顾问模式&quot;，没有切换到&quot;代理模式&quot;。</p><p>顾问模式（你做 AI 也在做）： 你：帮我写一个防抖函数 → AI：好的，这是代码 → 你：copy → 用</p><p>代理模式（你做决策 AI 执行）： 你：把这个模块的重构任务交给 AI，AI 生成 → 跑测试 → 报告结果</p><h2 id="_1-2-ai-的能力边界" tabindex="-1">1.2 AI 的能力边界 <a class="header-anchor" href="#_1-2-ai-的能力边界" aria-label="Permalink to &quot;1.2 AI 的能力边界&quot;">​</a></h2><h3 id="ai-擅长的事" tabindex="-1">AI 擅长的事 <a class="header-anchor" href="#ai-擅长的事" aria-label="Permalink to &quot;AI 擅长的事&quot;">​</a></h3><ul><li><strong>重复性代码生成</strong>：CRUD、格式化、类型定义</li><li><strong>代码解释和文档</strong>：给函数写注释、生成 README</li><li><strong>单函数重构</strong>：提取变量、改命名、简化逻辑</li><li><strong>测试生成</strong>：给定函数签名生成边界用例</li><li><strong>技术调研</strong>：解释概念、对比方案、找参考链接</li><li><strong>文案生成</strong>：PR 描述、CHANGELOG、提交信息</li></ul><h3 id="ai-不擅长的事" tabindex="-1">AI 不擅长的事 <a class="header-anchor" href="#ai-不擅长的事" aria-label="Permalink to &quot;AI 不擅长的事&quot;">​</a></h3><ul><li><strong>业务逻辑理解</strong>：不知道你项目的领域知识</li><li><strong>多文件关联修改</strong>：改了一个文件，需要改其他 N 个相关文件</li><li><strong>真实运行时行为</strong>：无法感知网络/数据库/第三方服务</li><li><strong>安全/并发/迁移</strong>：这些需要人来判断和兜底</li><li><strong>模糊需求</strong>：需求不清晰时 AI 会瞎猜</li></ul><h2 id="_1-3-有效协作的核心原则" tabindex="-1">1.3 有效协作的核心原则 <a class="header-anchor" href="#_1-3-有效协作的核心原则" aria-label="Permalink to &quot;1.3 有效协作的核心原则&quot;">​</a></h2><h3 id="原则-1-给-ai-足够上下文" tabindex="-1">原则 1：给 AI 足够上下文 <a class="header-anchor" href="#原则-1-给-ai-足够上下文" aria-label="Permalink to &quot;原则 1：给 AI 足够上下文&quot;">​</a></h3><p>差的 prompt（AI 瞎猜）： 写一个登录函数</p><p>好的 prompt（AI 知道要做什么）： 我用 Next.js + JWT + Cookie，实现会员登录：</p>',17),a("ul",null,[a("li",{"account,":"",password:""},"POST /api/login 接收"),a("li",null,"成功后 set-Cookie，key 是 Authorization"),a("li",null,"密码用 bcrypt.compare 比对"),a("li",null,"已经有 UserService.getByAccount 方法 请写这个 API 路由，用 TypeScript，参考项目现有风格")],-1),i('<h3 id="原则-2-让-ai-做闭环-不要只做一步" tabindex="-1">原则 2：让 AI 做闭环，不要只做一步 <a class="header-anchor" href="#原则-2-让-ai-做闭环-不要只做一步" aria-label="Permalink to &quot;原则 2：让 AI 做闭环，不要只做一步&quot;">​</a></h3><p>差的协作（AI 只做一步）： 你：写一个排序算法 → AI 写完 → 你 copy → 结束</p><p>好的协作（AI 做闭环）： 你：实现这个排序函数，要求： 1. 写函数 + 单元测试（覆盖边界：空数组、单元素、已排序、逆序） 2. 跑测试 3. 如果测试失败，修复后重新跑 4. 最后把结果报告给我</p><h3 id="原则-3-ai-的输出需要验证" tabindex="-1">原则 3：AI 的输出需要验证 <a class="header-anchor" href="#原则-3-ai-的输出需要验证" aria-label="Permalink to &quot;原则 3：AI 的输出需要验证&quot;">​</a></h3><p>AI 会产生&quot;幻觉&quot;（hallucination），包括：</p><ul><li><strong>虚假 API</strong>：声称某个库有这个函数，实际不存在</li><li><strong>错误类型</strong>：TypeScript 类型报错了，AI 说加 any 就行</li><li><strong>过期文档</strong>：引用了已废弃的 API 版本</li></ul><p>验证方法：</p><ul><li>跑测试 / 类型检查</li><li>查官方文档确认</li><li>问 AI：这个 API 在哪个版本引入的？</li></ul><h3 id="原则-4-拆解任务是-ai-能做的前提" tabindex="-1">原则 4：拆解任务是 AI 能做的前提 <a class="header-anchor" href="#原则-4-拆解任务是-ai-能做的前提" aria-label="Permalink to &quot;原则 4：拆解任务是 AI 能做的前提&quot;">​</a></h3><p>AI 搞不定的模糊任务： 你：把这个页面做国际化</p><p>AI 能搞定的拆解任务： 你：这个页面需要国际化： 1. 所有中文硬编码文本找出来（我给你文件路径） 2. 生成 i18n key 列表 3. 替换到代码中 4. 补充 zh/en 两个语言文件 5. 跑 lint 验证无遗漏</p><h2 id="_1-4-codex-专属概念" tabindex="-1">1.4 Codex 专属概念 <a class="header-anchor" href="#_1-4-codex-专属概念" aria-label="Permalink to &quot;1.4 Codex 专属概念&quot;">​</a></h2><h3 id="thread-线程" tabindex="-1">Thread（线程） <a class="header-anchor" href="#thread-线程" aria-label="Permalink to &quot;Thread（线程）&quot;">​</a></h3><p>Codex 中每个 Chat 就是一个 <strong>Thread</strong>，每个 Thread 有独立上下文：</p><ul><li>Thread 内 AI 能记住完整的对话历史</li><li>不同 Thread 之间的上下文<strong>不共享</strong></li><li>所以：每个任务开一个 Thread，避免上下文污染</li></ul><h3 id="skill-技能" tabindex="-1">Skill（技能） <a class="header-anchor" href="#skill-技能" aria-label="Permalink to &quot;Skill（技能）&quot;">​</a></h3><p>预置的 AI 行为规范：</p><ul><li>/automate — 创建自动化任务</li><li>/autopilot — 保持 PR 处于可合并状态</li><li>/review — AI Code Review</li><li>/canvas — 生成可视化图表</li></ul><h3 id="agent-子代理" tabindex="-1">Agent（子代理） <a class="header-anchor" href="#agent-子代理" aria-label="Permalink to &quot;Agent（子代理）&quot;">​</a></h3><p>Codex 可以 Spawn 子 Agent 独立执行任务：</p><ul><li>主 Agent 做规划和协调</li><li>子 Agent 并行执行独立子任务</li><li>适用于：多个文件同时修改、并行调研</li></ul><h3 id="worktree-工作树" tabindex="-1">Worktree（工作树） <a class="header-anchor" href="#worktree-工作树" aria-label="Permalink to &quot;Worktree（工作树）&quot;">​</a></h3><p>独立的 Git 分支 checkout，互不干扰：</p><ul><li>适合：实验性重构、不确定是否要合并的工作</li><li>每个 Worktree 有独立文件系统</li><li>主线程和 Worktree 之间可以切换</li></ul><h2 id="_1-5-本章小结" tabindex="-1">1.5 本章小结 <a class="header-anchor" href="#_1-5-本章小结" aria-label="Permalink to &quot;1.5 本章小结&quot;">​</a></h2><p>AI 协作的核心在于：把 AI 当作一个<strong>初级工程师</strong>而不是搜索引擎。</p><ul><li>给足够的上下文（项目信息 + 需求描述 + 约束条件）</li><li>拆解任务，让 AI 做闭环</li><li>AI 输出必须验证（跑测试 / 类型检查）</li><li>用 Codex 的 Thread / Skill / Agent 提升协作效率</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./02-工具链">02-工具链</a> — 了解主流 AI 编程工具及各自适用场景</li></ul><h2 id="面试常考" tabindex="-1">面试常考 <a class="header-anchor" href="#面试常考" aria-label="Permalink to &quot;面试常考&quot;">​</a></h2><h3 id="q1-ai-编程的两种使用模式" tabindex="-1">Q1:AI 编程的两种使用模式? <a class="header-anchor" href="#q1-ai-编程的两种使用模式" aria-label="Permalink to &quot;Q1:AI 编程的两种使用模式?&quot;">​</a></h3><p><strong>答</strong>:</p><ul><li><strong>Copilot 模式</strong>:实时补全、写单段代码;IDE 内</li><li><strong>Agent 模式</strong>:接受任务、端到端改动;CLI / IDE 插件</li><li>选:小改用 Copilot;大任务用 Agent</li><li>未来:Agent 模式占比越来越大</li></ul><h3 id="q2-ai-编程的-3-大局限" tabindex="-1">Q2:AI 编程的 3 大局限? <a class="header-anchor" href="#q2-ai-编程的-3-大局限" aria-label="Permalink to &quot;Q2:AI 编程的 3 大局限?&quot;">​</a></h3><p><strong>答</strong>:</p><ol><li><strong>幻觉</strong>:编造不存在的 API;必须查文档/源码</li><li><strong>上下文限制</strong>:大项目容易&quot;看不全&quot;;需要精确范围</li><li><strong>执行盲点</strong>:不理解业务规则、团队约定;需明确约束</li></ol><h3 id="q3-有效协作-3-原则" tabindex="-1">Q3:有效协作 3 原则? <a class="header-anchor" href="#q3-有效协作-3-原则" aria-label="Permalink to &quot;Q3:有效协作 3 原则?&quot;">​</a></h3><p><strong>答</strong>:</p><ul><li><strong>明确任务</strong>:目标 + 上下文 + 约束 + 验收标准</li><li><strong>小步迭代</strong>:复杂任务分步;每步确认</li><li><strong>验证输出</strong>:必读 diff;跑测试;看效果</li></ul>',39)])])}const I=t(o,[["render",n]]);export{c as __pageData,I as default};
